import React from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { 
  FaHome, FaCheckCircle, FaComments, FaClock, FaUserCircle, 
  FaSignOutAlt, FaBrain, FaBook, FaUserSecret, FaHeartbeat,
  FaFire, FaCalendarAlt, FaChartLine, FaUniversity
} from 'react-icons/fa';

function Navbar() {
  const navigate = useNavigate();
  const location = useLocation();

  const navItems = [
    { path: '/dashboard', icon: <FaHome />, label: 'Home' },
    { path: '/habits', icon: <FaCheckCircle />, label: 'Habits' },
    { path: '/chat', icon: <FaComments />, label: 'AI Chat' },
    { path: '/timer', icon: <FaClock />, label: 'Timer' },
    { path: '/burnout', icon: <FaBrain />, label: 'Burnout' },
    { path: '/academic-load', icon: <FaBook />, label: 'Academic' },
    { path: '/anonymous', icon: <FaUserSecret />, label: 'Anonymous' },
    { path: '/profile', icon: <FaUserCircle />, label: 'Profile' },
  ];

  const handleLogout = () => {
    localStorage.removeItem('isLoggedIn');
    localStorage.removeItem('userName');
    localStorage.removeItem('userEmail');
    localStorage.removeItem('userAvatar');
    localStorage.removeItem('userAvatarCategory');
    localStorage.removeItem('studentInfo');
    localStorage.removeItem('personalInfo');
    localStorage.removeItem('academicLoad');
    navigate('/');
  };

  return (
    <div style={styles.navbar}>
      <div style={styles.navContent}>
        <div style={styles.logo} onClick={() => navigate('/dashboard')}>
          <FaHeartbeat size={24} color="#667eea" />
          <span style={styles.logoText}>Mind<span style={{ color: '#764ba2' }}>Ease</span></span>
        </div>
        
        <div style={styles.navLinks}>
          {navItems.map((item) => (
            <div
              key={item.path}
              style={{
                ...styles.navItem,
                ...(location.pathname === item.path ? styles.navItemActive : {})
              }}
              onClick={() => navigate(item.path)}
            >
              {item.icon}
              <span style={styles.navLabel}>{item.label}</span>
            </div>
          ))}
          <div style={styles.navItem} onClick={handleLogout}>
            <FaSignOutAlt />
            <span style={styles.navLabel}>Logout</span>
          </div>
        </div>
      </div>
    </div>
  );
}

const styles = {
  navbar: {
    position: 'fixed',
    top: 0,
    left: 0,
    right: 0,
    background: 'white',
    boxShadow: '0 2px 10px rgba(0,0,0,0.08)',
    zIndex: 1000,
    padding: '8px 0',
  },
  navContent: {
    maxWidth: '1200px',
    margin: '0 auto',
    padding: '0 20px',
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    flexWrap: 'wrap',
    gap: '10px',
  },
  logo: {
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
    cursor: 'pointer',
  },
  logoText: {
    fontSize: '20px',
    fontWeight: 'bold',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
    WebkitBackgroundClip: 'text',
    WebkitTextFillColor: 'transparent',
  },
  navLinks: {
    display: 'flex',
    gap: '5px',
    flexWrap: 'wrap',
    alignItems: 'center',
  },
  navItem: {
    display: 'flex',
    alignItems: 'center',
    gap: '6px',
    padding: '8px 14px',
    borderRadius: '30px',
    cursor: 'pointer',
    transition: 'all 0.2s ease',
    color: '#666',
    fontSize: '14px',
  },
  navItemActive: {
    background: 'linear-gradient(135deg, #667eea15 0%, #764ba215 100%)',
    color: '#667eea',
  },
  navLabel: {
    fontSize: '13px',
    fontWeight: '500',
  },
};

export default Navbar;
